 SplitContainer MakeSplit(Orientation orientation,double ratio){var pane=new SplitContainer{Dock=DockStyle.Fill,Orientation=orientation,Size=new Size(900,600),SplitterWidth=6,Margin=new Padding(0),BackColor=SystemColors.Control};pane.Panel1.BackColor=pane.Panel2.BackColor=SystemColors.Window;pane.Panel1MinSize=pane.Panel2MinSize=35;bool sizing=false;pane.SizeChanged+=(sender,args)=>{if(sizing)return;int length=(orientation==Orientation.Horizontal?pane.Height:pane.Width)-pane.SplitterWidth;if(length<70)return;sizing=true;try{pane.SplitterDistance=Math.Max(35,Math.Min(length-35,(int)(length*ratio)));}finally{sizing=false;}};pane.SplitterMoving+=(sender,args)=>{int length=(orientation==Orientation.Horizontal?pane.Height:pane.Width)-pane.SplitterWidth;if(length>0)ratio=(double)(orientation==Orientation.Horizontal?args.SplitY:args.SplitX)/length;};return pane;}
 void AddPane(Control parent,Control content,Label label){var pane=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=2,ColumnCount=1,Margin=new Padding(0)};pane.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));pane.RowStyles.Add(new RowStyle(SizeType.Absolute,20));pane.RowStyles.Add(new RowStyle(SizeType.Percent,100));label.Dock=DockStyle.Fill;label.AutoEllipsis=true;content.Dock=DockStyle.Fill;pane.Controls.Add(label,0,0);pane.Controls.Add(content,0,1);parent.Controls.Add(pane);}
 const string TranslationPrefix="Translation: ";
 void RefreshTranslationChoices(){string selected=category.SelectedItem as string;binding=true;try{for(int i=category.Items.Count-1;i>=0;i--)if(((string)category.Items[i]).StartsWith(TranslationPrefix))category.Items.RemoveAt(i);if(session!=null)foreach(var translation in bridge.Game.Translations)category.Items.Add(TranslationPrefix+translation.FileName);category.SelectedItem=selected;if(category.SelectedIndex<0)category.SelectedIndex=0;}finally{binding=false;}}
 bool InCategory(LineItem line){string selected=category.SelectedItem as string;if(selected!=null&&selected.StartsWith(TranslationPrefix))return line.Target.Translation&&string.Equals(Path.GetFileName(line.Target.File),selected.Substring(TranslationPrefix.Length),StringComparison.OrdinalIgnoreCase);return category.SelectedIndex<=0?!line.Target.Translation:line.Category==selected;}
 List<LineItem> ExtractScope(){string selected=category.SelectedItem as string;bridge.Warnings.Clear();if(selected=="Translations"||(selected!=null&&selected.StartsWith(TranslationPrefix)))return bridge.ExtractProjectTranslations(selected=="Translations"?null:selected.Substring(TranslationPrefix.Length));return bridge.Extract().Where(InCategory).ToList();}
 void SyncLanguage(){syncingLanguage=true;try{reviewLanguage.SelectedItem=reviewLanguage.Items.Cast<CheckingLanguage>().FirstOrDefault(x=>session!=null&&x.longCode==session.State.Language);onlyPending.Checked=session!=null&&session.State.OnlyPending;}finally{syncingLanguage=false;}}
 string LanguageLabel(LineItem line){var language=reviewLanguage.Items.Cast<CheckingLanguage>().FirstOrDefault(x=>x.longCode==line.AssignedLanguage);return language==null?"Unassigned":language.ToString();}
 void SetDeferred(LineItem line){session.State.AssignedLanguages.TryGetValue(ReviewSession.LineKey(line),out line.AssignedLanguage);line.Deferred=!string.IsNullOrEmpty(line.AssignedLanguage)&&OfflineProof.BaseLanguage(line.AssignedLanguage)!=OfflineProof.BaseLanguage(session.State.Language);}
 List<LineItem> SelectedLines(){return grid.SelectedRows.Cast<DataGridViewRow>().Select(x=>x.Tag as LineItem).Where(x=>x!=null).ToList();}
 void IgnoreSelected(){if(busy||session==null)return;var selected=SelectedLines();foreach(var line in selected){string key=ReviewSession.LineKey(line);if(!session.State.IgnoredLines.Contains(key))session.State.IgnoredLines.Add(key);line.Ignored=true;line.Checked=true;foreach(var issue in line.Issues)issue.Ignored=true;}session.SaveState();Bind(null,0);status.Text=selected.Count+" lines ignored. "+Summary();}
 void AssignSelected(){if(busy||session==null)return;var selected=SelectedLines();var language=assignLanguage.SelectedItem as CheckingLanguage;foreach(var line in selected){string key=ReviewSession.LineKey(line);if(language==null)session.State.AssignedLanguages.Remove(key);else session.State.AssignedLanguages[key]=language.longCode;SetDeferred(line);}session.SaveState();Bind(null,0);status.Text=selected.Count+" language assignments saved. "+Summary();}
 void RestoreLine(LineItem line){LanguageDetection detection;session.State.Detections.TryGetValue(line.Entry.Key,out detection);line.Detection=null;SetDeferred(line);line.Issues=new List<Issue>();line.Checked=false;line.Reviewed=false;line.Ignored=session.State.Ignored.Contains(line.Entry.Key)||session.State.IgnoredLines.Contains(ReviewSession.LineKey(line));if(line.Ignored)line.Checked=true;var original=session.State.Reviewed.LastOrDefault(x=>x.Target==line.Target.Key&&x.Ordinal==line.Ordinal&&x.Text==line.Text);if(original!=null)line.Original=original.Original;var remembered=session.ReviewFor(line);if(!line.Ignored&&remembered!=null&&remembered.Verified&&remembered.Configuration==session.Configuration){line.Issues=remembered.Results.Select(x=>x.Copy()).ToList();ReviewSession.SetStatus(line);}}
 void ChangeLanguage(string language){draftTimer.Stop();draftGeneration++;session.State.Language=language;session.SaveState();SyncLanguage();foreach(var line in lines)RestoreLine(line);Bind(null,0);status.Text=Summary()+" Press Scan to check any rows marked Needs scan.";}
 bool InLanguage(LineItem line){return !line.Deferred;}
 void Button(Control parent,Button button,string text,Action action,string help){button.Text=text;button.AutoSize=true;button.Height=28;button.Margin=new Padding(0,2,6,2);button.Click+=(s,e)=>Run(action);tips.SetToolTip(button,help);parent.Controls.Add(button);}
 void AddColumn(string key,string header,int weight,int min){grid.Columns.Add(new DataGridViewTextBoxColumn{Name=key,HeaderText=header,FillWeight=weight,MinimumWidth=min,SortMode=DataGridViewColumnSortMode.Programmatic});}
 public void RefreshProject(){if(bridge.Game==null||string.IsNullOrEmpty(bridge.Root)){status.Text="Open an AGS game first.";return;}if(session==null||!string.Equals(session.Root,Path.GetFullPath(bridge.Root),StringComparison.OrdinalIgnoreCase))ResetProject();}
 public void ResetProject(){generation++;busy=false;lines.Clear();cache.Clear();session=null;Run(()=>{if(bridge.Game!=null&&!string.IsNullOrEmpty(bridge.Root)){session=new ReviewSession(bridge);title.Text="AGS Spellchecker  /  "+new DirectoryInfo(session.Root).Name;}});SyncLanguage();RefreshTranslationChoices();Bind(null,0);status.Text="Scan the open game to begin. Offline LanguageTool spelling, grammar and punctuation. Language: "+(session==null?"open a game":session.State.Language)+".";}
 string CacheKey(LineItem x){return session.Configuration+"|"+(x.Entry.Prose?"p:":"l:")+x.Text;}
 List<Issue> Check(string text,bool prose){return checker.Check(text,session.State.Language,session.State.Words.ToArray());}
 async void Scan(bool reuse){if(busy)return;RefreshProject();if(session==null)return;RefreshTranslationChoices();int token=++generation;busy=true;UpdateActions();draftTimer.Stop();draftGeneration++;status.Text="Reading text and starting the offline engine (first scan may take a moment)…";string selected=Selected==null?null:Selected.Identity;int index=grid.CurrentRow==null?0:grid.CurrentRow.Index;
  try{await Task.Delay(1);if(token!=generation)return;bridge.CheckCapabilities();var found=ExtractScope();int count=0,skipped=0;foreach(var line in found){if(token!=generation)return;RestoreLine(line);if(line.Deferred||line.Checked){skipped++;}else{ProofResult result;string key=CacheKey(line);if(!cache.TryGetValue(key,out result)){string checkLanguage=session.State.Language;string[] knownWords=session.State.Words.ToArray();result=await Task.Run(()=>checker.CheckDetailed(line.Text,checkLanguage,knownWords));if(token!=generation)return;cache[key]=result;}line.Detection=result.Detection;SetDeferred(line);if(!line.Deferred){var remembered=session.ReviewFor(line);line.Issues=result.Issues.Select(x=>x.Copy()).ToList();if(remembered!=null&&remembered.Results!=null)ReviewSession.CarryIgnored(line.Text,line.Text,remembered.Results,line.Issues);session.Remember(line,true,false);}}count++;if(count%16==0){status.Text="Checking "+count+" of "+found.Count+" lines…";await Task.Delay(1);}}if(token!=generation)return;session.SaveState();lines=found;busy=false;Bind(selected,index);status.Text=Summary()+" "+skipped+" cached/deferred lines skipped.";if(bridge.Warnings.Count>0)status.Text+=" "+bridge.Warnings.Count+" sources skipped — see History / settings.";}
  catch(Exception ex){if(token==generation){busy=false;status.Text="Scan could not finish: "+ex.Message;}}finally{if(token==generation){busy=false;UpdateActions();}}
 }
 string Summary(){var visible=lines.Where(InLanguage).ToList();return visible.Count(x=>x.Pending)+" unchecked · "+visible.Count(x=>x.Reviewed&&!x.Ignored)+" checked · "+visible.Count(x=>x.Ignored)+" ignored · "+lines.Count(x=>x.Deferred)+" assigned to other languages. Ctrl/Shift selects multiple rows.";}
 void Bind(string identity,int index){if(IsDisposed)return;binding=true;try{grid.Rows.Clear();if(session!=null){var query=lines.Where(InLanguage);if(onlyPending.Checked)query=query.Where(x=>x.Pending);query=query.Where(InCategory);if(search.TextLength>0)query=query.Where(x=>(x.Text+" "+x.Original+" "+x.Source).IndexOf(search.Text,StringComparison.CurrentCultureIgnoreCase)>=0);Func<LineItem,IComparable> key=x=>sort=="Count"?(IComparable)x.Count:sort=="Category"?x.Category:sort=="Text"?x.Text:sort=="Original"?x.Original:sort=="Language"?LanguageLabel(x):sort=="Status"?x.Status:x.Source;var sorted=ascending?query.OrderBy(key):query.OrderByDescending(key);foreach(var line in sorted){int n=grid.Rows.Add(line.Status,line.Count,LanguageLabel(line),line.Category,line.Source,line.Original,line.Entry.Preview);var row=grid.Rows[n];row.Tag=line;row.DefaultCellStyle.BackColor=line.Ignored?Color.FromArgb(219,234,254):line.Reviewed?Color.FromArgb(220,252,231):Color.FromArgb(254,226,226);row.DefaultCellStyle.ForeColor=Color.FromArgb(30,30,30);row.DefaultCellStyle.SelectionBackColor=line.Ignored?Color.FromArgb(30,80,155):line.Reviewed?Color.FromArgb(25,105,55):Color.FromArgb(150,40,40);row.DefaultCellStyle.SelectionForeColor=Color.White;}if(grid.Rows.Count>0){int n=identity==null?-1:grid.Rows.Cast<DataGridViewRow>().ToList().FindIndex(r=>((LineItem)r.Tag).Identity==identity);if(n<0)n=Math.Min(index,grid.Rows.Count-1);grid.ClearSelection();grid.CurrentCell=grid.Rows[Math.Max(0,n)].Cells[0];grid.Rows[Math.Max(0,n)].Selected=true;}}foreach(DataGridViewColumn c in grid.Columns)c.HeaderCell.SortGlyphDirection=c.Name==sort?(ascending?SortOrder.Ascending:SortOrder.Descending):SortOrder.None;}finally{binding=false;}Details();}
 void Details(){binding=true;try{var line=Selected;edit.Text=line==null?"":line.Text;location.Text=line==null?"No potential issues in this view":line.Source+" — edit below, then Apply & next";context.Text="";if(line!=null){if(line.Target.Script){string[] raw=line.Target.Snapshot.Replace("\r\n","\n").Split('\n');int n=Project.Line(line.Target.Snapshot,line.Entry.Start)-1;context.Text=string.Join(Environment.NewLine,raw.Select((s,i)=>new{i,s}).Where(x=>x.i>=n-2&&x.i<=n+2).Select(x=>(x.i==n?"> ":"  ")+(x.i+1)+"  "+x.s));}else context.Text=line.Target.Caption+Environment.NewLine+"Current value: "+line.Text;}}finally{binding=false;}CheckDraft();}
 void CheckDraft(){draftGeneration++;draftTimer.Stop();issues.Items.Clear();draftIssues.Clear();suggestions.Items.Clear();PreviewSuggestion();UpdateActions();if(session!=null&&Selected!=null&&!busy&&grid.SelectedRows.Count==1){if(edit.Text==Selected.Text){draftIssues=Selected.Issues.ToList();foreach(var issue in draftIssues)issues.Items.Add(issue);if(issues.Items.Count>0){int next=issues.Items.Cast<Issue>().ToList().FindIndex(x=>!x.Ignored);issues.SelectedIndex=next<0?0:next;}SuggestionList();}else draftTimer.Start();}}
 async void CheckDraftNow(){if(IsDisposed||session==null||Selected==null||busy||grid.SelectedRows.Count!=1)return;int token=draftGeneration;string text=edit.Text,lang=session.State.Language;string[] words=session.State.Words.ToArray();try{var result=await Task.Run(()=>checker.Check(text,lang,words));if(IsDisposed||token!=draftGeneration)return;draftIssues=result;foreach(var issue in result)issues.Items.Add(issue);if(issues.Items.Count>0){int next=issues.Items.Cast<Issue>().ToList().FindIndex(x=>!x.Ignored);issues.SelectedIndex=next<0?0:next;}SuggestionList();}catch(Exception ex){if(!IsDisposed&&token==draftGeneration)status.Text="Checking failed: "+ex.Message;}} void SuggestionList(){suggestions.Items.Clear();PreviewSuggestion();var issue=issues.SelectedItem as Issue;if(issue!=null&&!issue.Ignored){foreach(string s in issue.Suggestions)suggestions.Items.Add(s);if(suggestions.Items.Count>0)suggestions.SelectedIndex=0;}UpdateActions();}
 void PreviewSuggestion(){suggestionPreview.Clear();previewLabel.Text="Suggested line — change highlighted";var issue=issues.SelectedItem as Issue;var replacement=suggestions.SelectedItem as string;if(issue==null||replacement==null||issue.Ignored||issue.Start<0||issue.Start+issue.Length>edit.TextLength)return;suggestionPreview.Text=edit.Text.Remove(issue.Start,issue.Length).Insert(issue.Start,replacement);suggestionPreview.SelectAll();suggestionPreview.SelectionBackColor=SystemColors.Window;suggestionPreview.SelectionColor=SystemColors.WindowText;suggestionPreview.Select(issue.Start,replacement.Length);if(replacement.Length>0)suggestionPreview.SelectionBackColor=Color.FromArgb(255,235,120);else previewLabel.Text="Suggested line — removes \""+edit.Text.Substring(issue.Start,issue.Length).Replace("\r"," ").Replace("\n"," ")+"\"";suggestionPreview.ScrollToCaret();suggestionPreview.Select(issue.Start,0);}
 void UseSuggestion(){var issue=issues.SelectedItem as Issue;var suggestion=suggestions.SelectedItem as string;if(grid.SelectedRows.Count!=1||issue==null||suggestion==null)return;int pos=issue.Start;edit.Text=edit.Text.Remove(pos,issue.Length).Insert(pos,suggestion);Apply();}
 void Advance(LineItem previous,int index){var order=grid.Rows.Cast<DataGridViewRow>().Select(r=>(LineItem)r.Tag).ToList();var next=previous.Pending?previous:order.Skip(index+1).Concat(order.Take(index)).FirstOrDefault(x=>x!=previous&&x.Pending);Bind(next==null?previous.Identity:next.Identity,index);if(grid.CurrentRow!=null)grid.FirstDisplayedScrollingRowIndex=grid.CurrentRow.Index;status.Text=Summary();if(next==null)status.Text+=" No other unchecked lines in this view.";}
 void Apply(){if(grid.SelectedRows.Count!=1)return;var line=Selected;if(line==null||line.Text==edit.Text)return;ReplaceLine(line,edit.Text,false);}
 void Revert(){if(grid.SelectedRows.Count!=1)return;var line=Selected;if(line==null||line.Original==line.Text)return;ReplaceLine(line,line.Original,true);}
 void IgnoreIssue(){var line=Selected;var issue=issues.SelectedItem as Issue;if(line==null||issue==null||issue.Ignored)return;int index=grid.CurrentRow.Index;issue.Ignored=true;var actual=line.Issues.FirstOrDefault(x=>x.RuleId==issue.RuleId&&x.Start==issue.Start&&x.Length==issue.Length);if(actual!=null)actual.Ignored=true;session.Remember(line,true);Advance(line,index);}
 async void ReplaceLine(LineItem line,string replacement,bool restoring){if(busy)return;int index=grid.CurrentRow.Index;int token=generation;busy=true;draftTimer.Stop();draftGeneration++;UpdateActions();status.Text="Checking this line's remaining issues…";
  try{string language=session.State.Language;string[] words=session.State.Words.ToArray();var result=await Task.Run(()=>checker.CheckDetailed(replacement,language,words));if(IsDisposed||generation!=token)return;ReviewSession.CarryIgnored(line.Text,replacement,line.Issues,result.Issues);
  string assignmentKey=ReviewSession.LineKey(line);string assignedLanguage=line.AssignedLanguage;string before=line.Target.Snapshot;string raw=line.Entry.Kind=="script"?Project.Escape(replacement):replacement;string after=line.Target.Script?before.Remove(line.Entry.Start,line.Entry.Length).Insert(line.Entry.Start,raw):replacement;int delta=raw.Length-line.Entry.Length;int start=line.Entry.Start;
  session.Apply(line,replacement);
  foreach(var item in lines.Where(x=>x.Target.Key==line.Target.Key)){item.Target.Snapshot=after;if(item.Entry.Source!=null)item.Entry.Source.Text=after;if(item!=line&&item.Entry.Start>start)item.Entry.Start+=delta;if(item.Target.Script)item.Entry.Location="line "+Project.Line(after,item.Entry.Start);}
  line.Entry.Text=replacement;if(!string.IsNullOrEmpty(assignedLanguage)){session.State.AssignedLanguages.Remove(assignmentKey);session.State.AssignedLanguages[ReviewSession.LineKey(line)]=assignedLanguage;}line.Entry.Length=raw.Length;line.Issues=result.Issues;line.Detection=result.Detection;SetDeferred(line);session.Remember(line,true);busy=false;
  if(restoring){Bind(line.Identity,index);status.Text="Original text restored. "+Summary();}else Advance(line,index);
  }catch(Exception ex){if(!IsDisposed&&generation==token){busy=false;Run(()=>{throw new IOException(ex.Message,ex);});}}finally{if(!IsDisposed&&generation==token){busy=false;UpdateActions();}}
 } void AddWord(){var issue=issues.SelectedItem as Issue;if((issue==null||!issue.DictionaryEligible)&&edit.SelectionLength==0)return;int index=grid.CurrentRow.Index;var selected=Selected;session.AddWord(edit.SelectionLength>0?edit.SelectedText:edit.Text.Substring(issue.Start,issue.Length));cache.Clear();foreach(var line in lines.Where(x=>x.Checked&&!x.Ignored)){line.Issues=line.Issues.Where(x=>!OfflineProof.AcceptedIssue(line.Text,x.Start,x.Length,session.State.Words)).ToList();if(line.Count==0)line.Reviewed=true;}Advance(selected,index);}
 void Navigate(){Run(()=>{var line=Selected;if(line==null)return;line.Target.Navigate(line.Target.Script?Project.Line(line.Target.Snapshot,line.Entry.Start):1);});}
 void UpdateActions(){bool selected=grid.SelectedRows.Count==1&&Selected!=null&&Selected.Checked&&!Selected.Deferred&&session!=null&&!busy;reviewLanguage.Enabled=session!=null&&!busy;onlyPending.Enabled=session!=null&&!busy;category.Enabled=session!=null&&!busy;bulkIgnore.Enabled=assign.Enabled=session!=null&&!busy&&grid.SelectedRows.Count>0;assignLanguage.Enabled=session!=null&&!busy;scan.Enabled=session!=null&&!busy;cancel.Enabled=busy;go.Enabled=Selected!=null&&session!=null&&!busy;apply.Enabled=selected&&edit.Text!=Selected.Text;ignore.Enabled=selected&&issues.SelectedItem is Issue&&!((Issue)issues.SelectedItem).Ignored;word.Enabled=selected&&(edit.SelectionLength>0||(issues.SelectedItem is Issue&&((Issue)issues.SelectedItem).DictionaryEligible));use.Enabled=selected&&suggestions.SelectedItem!=null;revert.Enabled=selected&&Selected.Original!=Selected.Text;mark.Enabled=selected&&Selected.Pending;edit.ReadOnly=!selected;grid.Enabled=!busy;}
 void Run(Action action){try{action();}catch(Exception ex){status.Text=ex.Message;MessageBox.Show(this,ex.Message,"AGS Spellchecker",MessageBoxButtons.OK,MessageBoxIcon.Information);}UpdateActions();}
 void Help(){MessageBox.Show(this,"1. Scan checks player-facing text in the open project. Rows stay visible: red means not checked, green means checked, and blue means ignored. Filter by type or click a column heading to sort.\n\n2. Select a line. Use suggestion saves the selected correction and advances immediately. You can also type your own correction and choose Apply & next. Go to source opens its script line or property in AGS.\n\n3. Apply & next backs up the original, saves through AGS, then selects the next issue. This also saves other pending AGS edits. Ignore and Add word are remembered for this game.\n\nThe Original text column preserves the text before correction. Revert selected restores that line without undoing other corrections. Each issue is reviewed separately. Ignore accepts only the selected issue. A line stays red until every issue is corrected or ignored. Saved issue results are reused while text and dictionary settings are unchanged. History shows the backup folder.\n\nAll checking runs offline in the bundled LanguageTool engine. Choose Check language, then Scan. Ctrl/Shift selects multiple rows: Ignore selected accepts entire lines; Set language and Assign selected label those lines for the chosen language. Unassigned lines appear in all languages. Only unchecked / unresolved hides completed rows. Choose Translations or a registered translation in Show text in to check AGS project translations. Choose All player-facing text to return to game text. Drag panel dividers to resize the view. Coverage varies by language; dialogue fragments and informal speech may be intentional. Custom text-display wrappers and text assembled from variables may need manual review. Hover over buttons for help.","Using AGS Spellchecker",MessageBoxButtons.OK,MessageBoxIcon.Information);}
 void Settings(){if(session==null||busy)return;using(var form=new Form{Text="AGS Spellchecker — history and settings",Size=new Size(800,560),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=true}){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=4,Padding=new Padding(12)};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,35));layout.RowStyles.Add(new RowStyle(SizeType.Percent,100));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,45));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,40));form.Controls.Add(layout);var label=new Label{Dock=DockStyle.Fill,Text="Backups: "+session.Store,AutoEllipsis=true};tips.SetToolTip(label,session.Store);layout.Controls.Add(label,0,0);var history=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=false,Dock=DockStyle.Fill};history.Text=string.Join(Environment.NewLine,session.State.History.AsEnumerable().Reverse().Select(x=>x.When+"  "+(x.Undone?"UNDONE":x.Saved?"SAVED":"SAVE INCOMPLETE")+"  "+x.Caption+Environment.NewLine+"  "+x.BeforeText+" → "+x.AfterText))+Environment.NewLine+Environment.NewLine+"Scan warnings:"+Environment.NewLine+string.Join(Environment.NewLine,bridge.Warnings);layout.Controls.Add(history,0,1);var settings=new FlowLayoutPanel{Dock=DockStyle.Fill};layout.Controls.Add(settings,0,2);settings.Controls.Add(new Label{Text="Language:",AutoSize=true,Margin=new Padding(0,8,6,0)});var language=new ComboBox();language.DropDownStyle=ComboBoxStyle.DropDownList;language.Width=210;foreach(var item in checker.Languages().Where(x=>x.longCode!="en").OrderBy(x=>x.name)){language.Items.Add(item);if(item.longCode==session.State.Language)language.SelectedItem=item;}settings.Controls.Add(language);Button(settings,new Button(),"Reset ignored issues",()=>Run(()=>{session.State.Ignored.Clear();session.State.IgnoredLines.Clear();foreach(var record in session.State.Reviewed)foreach(var issue in record.Results??new List<Issue>())issue.Ignored=false;foreach(var line in lines){foreach(var issue in line.Issues)issue.Ignored=false;ReviewSession.SetStatus(line);}session.SaveState();form.Close();Bind(null,0);status.Text="Settings saved. Press Scan to check text with these settings.";}),"Restore ignored issues for review in this game.");Button(settings,new Button(),"Edit dictionary",()=>Dictionary(form),"Add or remove game-specific words, one word per line.");var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};layout.Controls.Add(footer,0,3);Button(footer,new Button(),"Done",()=>{var selectedLanguage=language.SelectedItem as CheckingLanguage;string lang=selectedLanguage==null?session.State.Language:selectedLanguage.longCode;if(lang!=session.State.Language){ChangeLanguage(lang);form.Close();}else form.Close();},"Return to review.");form.ShowDialog(this);}}
 void Dictionary(Form parent){using(var form=new Form{Text="Game dictionary — one word per line",Size=new Size(400,450),StartPosition=FormStartPosition.CenterParent}){var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ScrollBars=ScrollBars.Vertical,Text=string.Join(Environment.NewLine,session.State.Words.OrderBy(x=>x))};var save=new Button{Text="Save dictionary",Dock=DockStyle.Bottom,Height=35};form.Controls.Add(text);form.Controls.Add(save);save.Click+=(s,e)=>Run(()=>{session.State.Words=text.Text.Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries).Select(OfflineProof.NormalizeWord).Where(x=>x.Length>0).Distinct().ToList();session.SaveState();form.Close();parent.Close();cache.Clear();lines.Clear();Bind(null,0);status.Text="Dictionary saved. Press Scan to check with the updated dictionary.";});form.ShowDialog(parent);}}
}
